 rr=np.asarray(rr);cc=np.asarray(cc);o=np.lexsort((cc,rr));rr=rr[o];cc=cc[o];u=np.ones(len(rr),bool);u[1:]=(rr[1:]!=rr[:-1])|(cc[1:]!=cc[:-1]);rr=rr[u];cc=cc[u];ind=np.zeros(n+1,np.int64);np.add.at(ind,rr+1,1);ind=np.cumsum(ind)
